/**
 * The shared anchor-name golden vectors (`fixtures/anchor-names.vectors.json`).
 * The same file drives the contracts suite (EFSIndexer acceptance + EFSRouter
 * path canonicalization), so the TS codec and the Solidity side are checked
 * against one artifact instead of drifting apart. The vectors were written from
 * specs/02, not generated by this codec — a failure here is a real divergence.
 */

import { describe, expect, it } from 'vitest'
import {
  InvalidAnchorNameError,
  asCanonicalName,
  decodeName,
  encodeName,
  isCanonicalName,
} from '../src/names/segment.js'
import vectors from './fixtures/anchor-names.vectors.json' with { type: 'json' }

const caught = (fn: () => unknown): unknown => {
  try {
    fn()
  } catch (err) {
    return err
  }
  return undefined
}

describe('anchor-name golden vectors — accept', () => {
  it.each(vectors.accept)('encodes $input', ({ input, canonical }) => {
    expect(encodeName(input)).toBe(canonical)
    expect(isCanonicalName(canonical)).toBe(true)
    expect(decodeName(canonical)).toBe(input.normalize('NFC'))
    // The router test relies on this: a generic web3:// client percent-decodes
    // the path, and for a canonical name that yields exactly the human form.
    expect(decodeURIComponent(canonical)).toBe(input.normalize('NFC'))
  })
})

describe('anchor-name golden vectors — reject', () => {
  it.each([...vectors.reject, ...vectors.sdkOnlyReject])(
    'rejects $canonical ($reason)',
    ({ canonical, reason }) => {
      expect(isCanonicalName(canonical)).toBe(false)
      const err = caught(() => asCanonicalName(canonical))
      expect(err).toBeInstanceOf(InvalidAnchorNameError)
      expect((err as InvalidAnchorNameError).reason).toBe(reason)
    },
  )
})
